"""Shared MineNight shell for public gameplay statistics."""
from pathlib import Path
import hashlib
root=Path(__file__).resolve().parents[1]
home=(root/'src/index.html').read_text(encoding='utf-8')
header=home.split('  <main id="main"',1)[0].replace('href="index.html" aria-current="page"','href="index.html"')
header=header.replace('href="#practice"','href="index.html#practice"').replace('href="#worlds"','href="index.html#worlds"')
for asset in ['players.css','players.js']:
 version=hashlib.sha256((root/'src'/asset).read_bytes()).hexdigest()[:12]
 tag=f'<link rel="stylesheet" href="{asset}?v={version}">' if asset.endswith('css') else f'<script src="{asset}?v={version}" defer></script>'
 header=header.replace('</head>',tag+'\n</head>')
footer='  <footer'+home.split('  <footer',1)[1]
search='''<form id="player-search" class="player-search" role="search"><label for="player-query">Find a player</label><div class="search-row"><input type="search" id="player-query" name="q" maxlength="16" pattern="[A-Za-z0-9_]{1,16}" placeholder="Minecraft username" autocomplete="off" required><button class="button stats-button" type="submit">Search players <span aria-hidden="true">↗</span></button></div><p class="small muted">Search MineNight players by username. Only synchronized server statistics are shown.</p></form><div id="search-results" class="search-results" aria-live="polite"></div>'''
pages={
 'leaderboard':('Leaderboard','Every fight counts.','See who leads MineNight. Explore kills, deaths and time spent on the server.',f'''<section class="stats-panel stats-search-panel">{search}</section><section class="stats-panel leaderboard-panel" aria-label="Player leaderboard"><div class="stats-panel-heading"><div><p class="eyebrow ice-text">THE MINENIGHT LEADERBOARD</p><h2 id="leaderboard-title">Most kills</h2></div><span id="player-total" class="small muted"></span></div><div class="stats-tabs" role="group" aria-label="Leaderboard statistic"><button type="button" data-metric="kills" aria-pressed="true">Kills</button><button type="button" data-metric="deaths" aria-pressed="false">Deaths</button><button type="button" data-metric="playtime" aria-pressed="false">Playtime</button><button type="button" disabled>Victory Royales <small>Coming Soon</small></button><button type="button" disabled>Event Wins <small>Coming Soon</small></button></div><div class="stats-table-scroll"><table class="stats-table"><caption class="sr-only">Top 50 players by selected statistic</caption><thead><tr><th scope="col">Rank</th><th scope="col">Player</th><th scope="col" id="value-heading">Kills</th></tr></thead><tbody id="leaderboard-rows"></tbody></table></div><p id="leaderboard-empty" class="stats-empty" hidden>No synchronized player statistics yet. Check back after the server's next update.</p></section>'''),
 'players':('Players','Find your next rival.','Look up a MineNight player and explore their server statistics.',f'''<section class="stats-panel stats-search-panel">{search}</section><section id="player-profile" class="stats-panel player-profile" hidden aria-labelledby="profile-name"><div class="profile-heading"><img id="player-skin" class="player-skin" width="160" height="300" alt="" hidden><div><p class="eyebrow ice-text">MINENIGHT PLAYER</p><h2 id="profile-name"></h2><p class="small muted">Lifetime server statistics</p></div><a class="text-link" href="leaderboard.html">View leaderboard ↗</a></div><div class="profile-stat-grid"><article><span>Kills</span><strong id="profile-kills"></strong><small id="rank-kills"></small></article><article><span>Deaths</span><strong id="profile-deaths"></strong><small id="rank-deaths"></small></article><article><span>Playtime</span><strong id="profile-playtime"></strong><small id="rank-playtime"></small></article><article class="future-stat"><span>Victory Royales</span><strong aria-label="Not available">—</strong><small>Coming Soon</small></article><article class="future-stat"><span>Event Wins</span><strong aria-label="Not available">—</strong><small>Coming Soon</small></article></div></section><section id="profile-placeholder" class="stats-panel stats-placeholder"><p class="eyebrow ice-text">KNOW THE PLAYER</p><h2>Your stats. Your story.</h2><p class="muted">Search for a Minecraft username above to view kills, deaths and playtime.</p><a class="text-link" href="leaderboard.html">Explore the leaderboard ↗</a></section>''')}
for slug,(title,heading,description,content) in pages.items():
 head=header.replace('MineNight · Home','MineNight · '+title).replace(f'href="{slug}.html"',f'href="{slug}.html" aria-current="page"')
 main=f'''  <main id="main" class="wrap stats-main" data-stats-page="{slug}" tabindex="-1"><nav class="breadcrumb" aria-label="Breadcrumb"><a href="index.html">MineNight</a><span aria-hidden="true">/</span><span aria-current="page">{title}</span></nav><header class="stats-hero"><p class="eyebrow ice-text">MINENIGHT · {title.upper()}</p><h1>{heading}</h1><p class="muted">{description}</p></header><p id="stats-message" class="stats-message" role="status" hidden></p>{content}<p id="stats-freshness" class="stats-freshness small muted" role="status">Loading server statistics…</p><p class="small muted stats-note">Victory Royales and Event Wins are coming soon. Their counters are not active yet.</p><noscript><p>Enable JavaScript to load player statistics.</p></noscript></main>'''
 (root/'src'/f'{slug}.html').write_text(head+main+footer,encoding='utf-8')
print('Generated leaderboard and searchable player profiles.')
